#include <array>
#include <iostream>
#include <string_view>

int main() {
    constexpr std::array<std::string_view, 5> milestones{
        "C++98", "C++11", "C++14", "C++17", "C++20/23"
    };
    for (std::size_t i = 0; i < milestones.size(); ++i) {
        if (i) std::cout << ", ";
        std::cout << milestones[i];
    }
    std::cout << '\n';
}
